cat > /home/vagrant/work/deploy/ue-http-get.pl <<'EOF'
#!/usr/bin/perl
# Minimal HTTP GET bound to a given interface (SO_BINDTODEVICE), so traffic
# is forced through the UE's 5G tunnel (uesimtun0). Usage: ue-http-get.pl <ifname> <ip> [port] [path]
use strict; use Socket;
my ($if,$ip,$port,$path)=@ARGV; $port||=80; $path||='/';
socket(my $s, PF_INET, SOCK_STREAM, getprotobyname('tcp')) or die "socket: $!";
setsockopt($s, SOL_SOCKET, 25, pack('Z*',$if)) or die "SO_BINDTODEVICE: $!";
local $SIG{ALRM}=sub{die "timeout\n"}; alarm 10;
connect($s, sockaddr_in($port, inet_aton($ip))) or die "connect: $!";
my $old=select($s); $|=1; select($old);
print $s "GET $path HTTP/1.0\r\nHost: $ip\r\nConnection: close\r\n\r\n";
print while <$s>;
EOF
kubectl -n free5gc cp /home/vagrant/work/deploy/ue-http-get.pl $(kubectl -n free5gc get pod -l component=ue -o name | head -1 | cut -d/ -f2):/tmp/ue-http-get.pl
kubectl -n free5gc exec deploy/ueransim-ue -- perl /tmp/ue-http-get.pl uesimtun0 10.43.200.10 80 /

